"""Prepare the existing static website for the 2.1.2 release; no network calls."""
from pathlib import Path
import re, shutil

ROOT = Path(__file__).resolve().parents[1]
WEB = ROOT/'web'
REPO = 'https://github.com/jianhx189/jianhx-game-stream'

def prepare():
    p = WEB/'index.html'
    text = p.read_text(encoding='utf-8-sig')
    text = text.replace('v2.1.1-preview', 'v2.1.2')
    text = text.replace('REAL DESKTOP APPS / 界面更新预览', 'REAL DESKTOP APPS / 2.1.2 正式版')
